/**
 * TimeStretchPrecompImport — generated by `remotion-ui import-ae` from time-stretch-precomp.json (Bodymovin 5.7.3).
 * 720×720 at 25 fps, 200 frames.
 *
 * Plain data on top of `ae-motion`: keyframe frames are this composition's
 * frames, speed is units per second, scale is a factor and opacity is 0–1.
 * Edit a key, a colour or a layer's inPoint/outPoint/startTime and re-render.
 */
import { AeComposition, AeLayer, precompLayer } from "@/remotion/lib/ae-import";
import { Comp0Precomp } from "./comp-0";

/** "测试2" — precomp layer (Comp0Precomp), frames 0–200. */
const layer2Layer = precompLayer({
  name: "测试2",
  inPoint: 0,
  outPoint: 200,
  timeStretch: 2,
  transform: { anchor: [360, 360], position: [360, 360] },
  width: 720,
  height: 720,
});

export const Layer2 = () => (
  <AeLayer layer={layer2Layer}>
    <Comp0Precomp />
  </AeLayer>
);

/** The composition. Layers are listed bottom of the AE timeline first — later ones draw on top. */
export const TimeStretchPrecompImport = () => (
  <AeComposition width={720} height={720} fps={25}>
    <Layer2 />
  </AeComposition>
);

/** Register with `<Composition {...config} />`; `remotion-ui import-ae` adds it to Root.tsx for you. */
export const timeStretchPrecompImportComposition = {
  id: "TimeStretchPrecompImport",
  component: TimeStretchPrecompImport,
  durationInFrames: 200,
  fps: 25,
  width: 720,
  height: 720,
};
